import dao.*;import model.*;import util.*;import java.sql.*;import java.math.BigDecimal;import java.util.*;import java.util.concurrent.*;

/** Compras verificadas, privacidade, deduplicação e rollback de avisos na base isolada. */
public final class AvaliacoesENotificacoes {
    private static Usuario admin,vendedor;private static Cliente cliente,outro;private static Produto produto;
    private static final AvaliacaoDAO aval=new AvaliacaoDAO();private static final NotificacaoDAO avisos=new NotificacaoDAO();private static int cenarios;
    public static void main(String[] args)throws Exception{
        exigir(texto("SELECT current_database()").equals("obotbarato_test"),"Base isolada obrigatória.");admin=new UsuarioDAO().autenticar("admin","admin123");vendedor=new UsuarioDAO().autenticar("vendedor","vendedor123");Sessao.iniciar(admin);produto=produto("Produto Avaliacao",30);
        cliente=cliente("Comprador Avaliacao","avaliacao@teste.local");outro=cliente("Outro Comprador Avaliacao","outraavaliacao@teste.local");
        Sessao.encerrar();negar(()->aval.salvar(1,produto.getId(),5,"Texto"),SQLException.class);negar(()->avisos.listar(false),SQLException.class);Sessao.iniciar(admin);negar(()->aval.salvar(1,produto.getId(),5,"Texto"),SQLException.class);ok("Sem sessão e equipe não publicam avaliações; notificações exigem identidade ativa");

        Sessao.iniciarCliente(cliente);UUID chave=UUID.randomUUID();int pedido=compra("pix",chave);
        exigir(numero("SELECT COUNT(*) FROM notificacoes WHERE id_pedido="+pedido)==2,"Criação não notificou cliente/equipe.");compra("pix",chave);exigir(numero("SELECT COUNT(*) FROM notificacoes WHERE id_pedido="+pedido)==2,"Retry duplicou avisos.");
        negar(()->aval.salvar(pedido,produto.getId(),5,"Antes da entrega"),IllegalArgumentException.class);Sessao.iniciar(admin);new GestaoPedidoDAO().avancar(pedido,"aberto","em_preparo");Sessao.iniciarCliente(cliente);negar(()->aval.salvar(pedido,produto.getId(),5,"Em preparo"),IllegalArgumentException.class);ok("Compra notifica sem duplicar no retry; avaliação bloqueada antes da entrega");

        Sessao.iniciar(admin);new GestaoPedidoDAO().avancar(pedido,"em_preparo","enviado");new GestaoPedidoDAO().avancar(pedido,"enviado","entregue");Sessao.iniciarCliente(outro);negar(()->aval.salvar(pedido,produto.getId(),5,"Pedido alheio"),IllegalArgumentException.class);
        Sessao.iniciarCliente(cliente);negar(()->aval.salvar(pedido,Integer.MAX_VALUE,5,"Produto não comprado"),IllegalArgumentException.class);negar(()->aval.salvar(pedido,produto.getId(),0,"Nota zero"),IllegalArgumentException.class);negar(()->aval.salvar(pedido,produto.getId(),6,"Nota seis"),IllegalArgumentException.class);negar(()->aval.salvar(pedido,produto.getId(),5,"x".repeat(1001)),IllegalArgumentException.class);ok("Pedido de outro titular, produto não adquirido, nota e comentário inválidos recusados");

        aval.salvar(pedido,produto.getId(),5,"Produto bem apresentado.");String criado=texto("SELECT criada_em::text FROM avaliacoes WHERE id_cliente="+cliente.getId()+" AND id_produto="+produto.getId());aval.salvar(pedido,produto.getId(),3,"Atualizei a avaliação.");
        exigir(numero("SELECT COUNT(*) FROM avaliacoes WHERE id_cliente="+cliente.getId()+" AND id_produto="+produto.getId())==1 && aval.minha(produto.getId()).nota()==3 && texto("SELECT criada_em::text FROM avaliacoes WHERE id_cliente="+cliente.getId()+" AND id_produto="+produto.getId()).equals(criado),"Editar duplicou avaliação ou perdeu criação.");
        paralelo(()->aval.salvar(pedido,produto.getId(),2,"Edição A"),()->aval.salvar(pedido,produto.getId(),4,"Edição B"));exigir(numero("SELECT COUNT(*) FROM avaliacoes WHERE id_cliente="+cliente.getId()+" AND id_produto="+produto.getId())==1,"Concorrência duplicou avaliação.");aval.salvar(pedido,produto.getId(),4,"Boa apresentação.");ok("Uma avaliação por cliente/produto; edição e concorrência preservam registro único");

        Sessao.iniciarCliente(outro);int segundo=compra("credito",UUID.randomUUID());Sessao.iniciar(admin);entregar(segundo);Sessao.iniciarCliente(outro);aval.salvar(segundo,produto.getId(),5,"Gostei do produto.");var disponivel=new ProdutoDAO().buscarParaCarrinho(produto.getId());exigir(disponivel.media().compareTo(new BigDecimal("4.5"))==0 && disponivel.avaliacoes()==2,"Média/count incorretos.");String publico=aval.listarProduto(produto.getId()).toString();exigir(!publico.contains(cliente.getEmail()) && !publico.contains(outro.getNome()),"Avaliações expõem dados cadastrais.");ok("Média de compradores distintos aparece no catálogo sem divulgar nome/e-mail/CPF");

        long avisoCliente=numero("SELECT MIN(id) FROM notificacoes WHERE id_pedido="+pedido+" AND destino='cliente'");negar(()->avisos.marcarLida(avisoCliente),IllegalArgumentException.class);exigir(avisos.listar(false).stream().allMatch(n->numeroSemErro("SELECT id_cliente FROM notificacoes WHERE id="+n.id())==outro.getId()),"Cliente recebeu aviso alheio.");Sessao.iniciarCliente(cliente);avisos.marcarLida(avisoCliente);avisos.marcarLida(avisoCliente);exigir(avisos.listar(true).stream().noneMatch(n->n.id()==avisoCliente) && numero("SELECT COUNT(*) FROM leituras_notificacoes WHERE id_notificacao="+avisoCliente)==1,"Leitura duplicou ou filtro falhou.");ok("Notificações privadas e leitura repetida idempotente; filtro de não lidas respeitado");

        long equipe=numero("SELECT MIN(id) FROM notificacoes WHERE id_pedido="+pedido+" AND destino='equipe'");Sessao.iniciar(vendedor);avisos.marcarLida(equipe);Sessao.iniciar(admin);exigir(avisos.listar(true).stream().anyMatch(n->n.id()==equipe),"Vendedor marcou aviso como lido para outro usuário.");negar(()->avisos.marcarLida(avisoCliente),IllegalArgumentException.class);ok("Equipe recebe avisos próprios, com leitura independente para admin e vendedor");

        Sessao.iniciarCliente(cliente);int boleto=compra("boleto",UUID.randomUUID());Sessao.iniciar(admin);new CompraDAO().confirmarPagamento(boleto);new CompraDAO().confirmarPagamento(boleto);exigir(numero("SELECT COUNT(*) FROM notificacoes WHERE id_pedido="+boleto+" AND tipo='pagamento'")==2,"Pagamento duplicou aviso.");Sessao.iniciarCliente(cliente);int cancelar=compra("credito",UUID.randomUUID());new GestaoPedidoDAO().cancelar(cancelar,"Desistência no teste");new GestaoPedidoDAO().cancelar(cancelar,"Repetição do teste");exigir(numero("SELECT COUNT(*) FROM notificacoes WHERE id_pedido="+cancelar)==4,"Cancelamento duplicou avisos.");negar(()->aval.salvar(cancelar,produto.getId(),5,"Cancelado"),IllegalArgumentException.class);ok("Pagamento e cancelamento notificam uma vez por evento; cancelado não pode avaliar");

        Sessao.iniciar(admin);Produto baixo=produto("Estoque Avisos",6);EstoqueDAO estoque=new EstoqueDAO();estoque.atualizar(baixo.getId(),5);estoque.atualizar(baixo.getId(),4);exigir(alertas(baixo)==1,"Saldo crítico repetido duplicou alerta.");estoque.entrada(baixo.getId(),6);estoque.saida(baixo.getId(),5);exigir(alertas(baixo)==2,"Nova queda após reposição não notificou.");estoque.definirMinimo(baixo.getId(),2);estoque.definirMinimo(baixo.getId(),5);exigir(alertas(baixo)==3,"Mínimo não participa do alerta.");Produto simultaneo=produto("Estoque Simultaneo Aviso",6);paralelo(()->estoque.atualizar(simultaneo.getId(),5),()->estoque.atualizar(simultaneo.getId(),5));exigir(alertas(simultaneo)==1,"Concorrência duplicou alerta.");ok("Estoque baixo gera um alerta por episódio, rearmado pela reposição/mínimo e sem duplicação concorrente");

        int saldo=new EstoqueDAO().getQuantidade(produto.getId());paralelo(()->{Pedido venda=new Pedido();venda.setIdCliente(cliente.getId());venda.setStatus("entregue");venda.adicionarItem(item());new PedidoDAO().salvar(venda);},()->estoque.entrada(produto.getId(),1));exigir(estoque.getQuantidade(produto.getId())==saldo,"Venda/reposição concorrente perdeu saldo.");ok("Venda e reposição simultâneas usam ordem consistente de bloqueios e conservam o saldo");

        Sessao.iniciarCliente(cliente);long pedidos=numero("SELECT COUNT(*) FROM pedidos"),mov=numero("SELECT COUNT(*) FROM movimentos_estoque"),notificacoes=numero("SELECT COUNT(*) FROM notificacoes");saldo=estoque.getQuantidade(produto.getId());
        sql("CREATE FUNCTION teste_aviso_falha() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'falha de notificacao proposital'; END $$");sql("CREATE TRIGGER teste_aviso BEFORE INSERT ON notificacoes FOR EACH ROW EXECUTE FUNCTION teste_aviso_falha()");
        try{negar(()->compra("pix",UUID.randomUUID()),SQLException.class);exigir(numero("SELECT COUNT(*) FROM pedidos")==pedidos && numero("SELECT COUNT(*) FROM movimentos_estoque")==mov && numero("SELECT COUNT(*) FROM notificacoes")==notificacoes && estoque.getQuantidade(produto.getId())==saldo,"Aviso falho deixou compra parcial.");}finally{sql("DROP TRIGGER teste_aviso ON notificacoes");sql("DROP FUNCTION teste_aviso_falha()");}ok("Falha ao notificar desfaz pedido, itens, estoque, histórico, pagamento e avisos");

        Sessao.iniciar(admin);Produto falho=produto("Alerta Falho",6);sql("CREATE FUNCTION teste_estoque_aviso_falha() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.tipo='estoque' THEN RAISE EXCEPTION 'falha proposital'; END IF; RETURN NEW; END $$");sql("CREATE TRIGGER teste_estoque_aviso BEFORE INSERT ON notificacoes FOR EACH ROW EXECUTE FUNCTION teste_estoque_aviso_falha()");
        try{negar(()->estoque.atualizar(falho.getId(),5),SQLException.class);exigir(estoque.getQuantidade(falho.getId())==6 && numero("SELECT episodio_alerta FROM estoque WHERE id_produto="+falho.getId())==0,"Alerta falho mudou saldo/episódio.");}finally{sql("DROP TRIGGER teste_estoque_aviso ON notificacoes");sql("DROP FUNCTION teste_estoque_aviso_falha()");}ok("Falha no alerta de estoque desfaz saldo, movimento e estado de deduplicação");

        new ProdutoDAO().excluir(produto.getId());Sessao.iniciarCliente(cliente);aval.salvar(pedido,produto.getId(),4,"");exigir(aval.minha(produto.getId()).comentario()==null && new ProdutoDAO().listarCatalogo("").stream().noneMatch(p->p.produto().getId()==produto.getId()),"Produto inativo/perfil opcional incorretos.");ok("Produto adquirido pode manter avaliação após desativação; comentário vazio opcional e item fora do catálogo");
        System.out.println("APROVADO: "+cenarios+" cenários de avaliações e notificações em PostgreSQL real.");
    }
    private static Produto produto(String nome,int saldo)throws Exception{Produto p=new Produto();p.setNome(nome);p.setPreco(new BigDecimal("10.00"));p.setIdCategoria(new CategoriaDAO().listar(false).get(0).id());p.setAtivo(true);p.setEstoqueInicial(saldo);new ProdutoDAO().salvar(p);return p;}
    private static Cliente cliente(String nome,String email)throws Exception{email=email.replace("@",UUID.randomUUID().toString().substring(0,8)+"@");ClienteLojaDAO d=new ClienteLojaDAO();exigir(d.cadastrar(nome,null,email,"11999990000","Rua Teste, 100","senha12345")==null,"Cadastro falhou.");return d.autenticar(email,"senha12345");}
    private static ItemPedido item(){ItemPedido i=new ItemPedido();i.setIdProduto(produto.getId());i.setQuantidade(1);i.setPrecoUnitario(produto.getPrecoDecimal());return i;}
    private static int compra(String metodo,UUID chave)throws SQLException{return new CompraDAO().confirmar(Sessao.getIdCliente(),List.of(item()),metodo,"Cliente Entrega","11999990000","Rua Entrega, 100",chave).id();}
    private static void entregar(int id)throws SQLException{GestaoPedidoDAO d=new GestaoPedidoDAO();d.avancar(id,"aberto","em_preparo");d.avancar(id,"em_preparo","enviado");d.avancar(id,"enviado","entregue");}
    private static long alertas(Produto p)throws SQLException{return numero("SELECT COUNT(*) FROM notificacoes WHERE tipo='estoque' AND id_produto="+p.getId());}
    private static void paralelo(Operacao a,Operacao b)throws Exception{ExecutorService ex=Executors.newFixedThreadPool(2);CountDownLatch inicio=new CountDownLatch(1);try{Future<?>fa=ex.submit(()->{inicio.await();a.executar();return null;}),fb=ex.submit(()->{inicio.await();b.executar();return null;});inicio.countDown();fa.get(30,TimeUnit.SECONDS);fb.get(30,TimeUnit.SECONDS);}finally{ex.shutdownNow();}}
    private static String texto(String s)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement p=c.createStatement();ResultSet r=p.executeQuery(s)){r.next();return r.getString(1);}}
    private static long numero(String s)throws SQLException{return Long.parseLong(texto(s));}private static long numeroSemErro(String s){try{return numero(s);}catch(SQLException e){throw new RuntimeException(e);}}
    private static void sql(String s)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement p=c.createStatement()){p.execute(s);}}
    @FunctionalInterface private interface Operacao{void executar()throws Exception;}
    private static void negar(Operacao op,Class<? extends Throwable> tipo)throws Exception{try{op.executar();}catch(Throwable e){if(tipo.isInstance(e))return;throw new AssertionError("Erro diferente do esperado.",e);}throw new AssertionError("Operação indevida aceita.");}
    private static void exigir(boolean b,String s){if(!b)throw new AssertionError(s);}private static void ok(String s){cenarios++;System.out.println("OK "+cenarios+": "+s);}
}
